-- HR/People Analytics Seed Data
-- Generated for insighting_demo PostgreSQL database
-- Contains 7 tables with correlated realistic data

BEGIN;

-- Drop tables in reverse FK order
DROP TABLE IF EXISTS employee_promotions CASCADE;
DROP TABLE IF EXISTS employee_learning CASCADE;
DROP TABLE IF EXISTS pulse_surveys CASCADE;
DROP TABLE IF EXISTS employee_recognition CASCADE;
DROP TABLE IF EXISTS performance_ratings CASCADE;
DROP TABLE IF EXISTS employee_attrition CASCADE;
DROP TABLE IF EXISTS employees CASCADE;

-- ============================================
-- Table: employees
-- ============================================
CREATE TABLE IF NOT EXISTS employees (
    id SERIAL PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    age INT,
    gender VARCHAR(10),
    department VARCHAR(50),
    designation VARCHAR(50),
    location VARCHAR(50),
    hire_date DATE,
    employment_type VARCHAR(20),
    salary NUMERIC(12,2),
    manager_id INT REFERENCES employees(id),
    is_active BOOLEAN
);

-- ============================================
-- Table: employee_attrition
-- ============================================
CREATE TABLE IF NOT EXISTS employee_attrition (
    id SERIAL PRIMARY KEY,
    employee_id INT REFERENCES employees(id),
    exit_date DATE,
    reason VARCHAR(100),
    last_department VARCHAR(50),
    tenure_months INT,
    exit_type VARCHAR(20),
    exit_interview_score NUMERIC(3,1)
);

-- ============================================
-- Table: performance_ratings
-- ============================================
CREATE TABLE IF NOT EXISTS performance_ratings (
    id SERIAL PRIMARY KEY,
    employee_id INT REFERENCES employees(id),
    review_period VARCHAR(20),
    rating INT,
    reviewer_id INT REFERENCES employees(id),
    goals_met_pct INT,
    comments TEXT,
    review_date DATE
);

-- ============================================
-- Table: employee_recognition
-- ============================================
CREATE TABLE IF NOT EXISTS employee_recognition (
    id SERIAL PRIMARY KEY,
    employee_id INT REFERENCES employees(id),
    recognized_by INT REFERENCES employees(id),
    recognition_type VARCHAR(50),
    category VARCHAR(50),
    points INT,
    awarded_date DATE
);

-- ============================================
-- Table: pulse_surveys
-- ============================================
CREATE TABLE IF NOT EXISTS pulse_surveys (
    id SERIAL PRIMARY KEY,
    employee_id INT REFERENCES employees(id),
    survey_date DATE,
    question_category VARCHAR(50),
    score INT,
    comments TEXT
);

-- ============================================
-- Table: employee_learning
-- ============================================
CREATE TABLE IF NOT EXISTS employee_learning (
    id SERIAL PRIMARY KEY,
    employee_id INT REFERENCES employees(id),
    course_name VARCHAR(200),
    category VARCHAR(50),
    status VARCHAR(20),
    completion_date DATE,
    score INT,
    hours_spent NUMERIC(5,1)
);

-- ============================================
-- Table: employee_promotions
-- ============================================
CREATE TABLE IF NOT EXISTS employee_promotions (
    id SERIAL PRIMARY KEY,
    employee_id INT REFERENCES employees(id),
    promotion_date DATE,
    old_designation VARCHAR(50),
    new_designation VARCHAR(50),
    old_department VARCHAR(50),
    new_department VARCHAR(50),
    salary_increase_pct NUMERIC(5,2)
);

